gtr(){return"\u092b\u093c\u0940\u0932\u094d\u0921 \u0915\u093e \u092e\u0924\u0932\u092c"},
gue(){return"\u0935\u091c\u093c\u0928"},
gud(){return"\u092c\u093e\u0930 \u092f\u093e \u092e\u0936\u0940\u0928 \u092a\u0930 \u0915\u093e\u092e \u0915\u093e \u092d\u093e\u0930\u0964 \u0915\u093f\u0932\u094b\u0917\u094d\u0930\u093e\u092e \u092f\u093e \u092a\u093e\u0909\u0902\u0921 \u0932\u093f\u0916\u0947\u0902 \u2014 \u0910\u092a \u0907\u0915\u093e\u0908 \u0928\u0939\u0940\u0902 \u092c\u0926\u0932\u0924\u0940 \u0914\u0930 \u091a\u0941\u0928\u093e\u0935 \u0928\u0939\u0940\u0902 \u0925\u094b\u092a\u0924\u0940\u0964"},
