gon(){return"\u0412 \u0442\u0430\u0431\u043b\u0438\u0446\u0435 \u043d\u0435\u0442 \u0441\u0442\u0440\u043e\u043a \u0434\u043b\u044f \u0438\u043c\u043f\u043e\u0440\u0442\u0430."},
gop(){return"\u042d\u0442\u043e \u043b\u0438\u0447\u043d\u044b\u0439 \u0434\u043d\u0435\u0432\u043d\u0438\u043a. \u0418\u043c\u043f\u043e\u0440\u0442\u0438\u0440\u0443\u0439\u0442\u0435 \u0435\u0433\u043e \u0432 \u0440\u0435\u0436\u0438\u043c\u0435 \xab\u0422\u0440\u0435\u043d\u0438\u0440\u0443\u044e\u0441\u044c \u0441\u0430\u043c\xbb."},
gol(){return"\u042d\u0442\u043e \u0442\u0430\u0431\u043b\u0438\u0446\u0430 \u0442\u0440\u0435\u043d\u0435\u0440\u0430. \u0418\u043c\u043f\u043e\u0440\u0442\u0438\u0440\u0443\u0439\u0442\u0435 \u0435\u0451 \u0432 \u0440\u0435\u0436\u0438\u043c\u0435 \xab\u0422\u0440\u0435\u043d\u0438\u0440\u0443\u044e \u0434\u0440\u0443\u0433\u0438\u0445\xbb."},
goo(){return"\u041c\u0435\u043d\u044f\u0442\u044c \u043d\u0435\u0447\u0435\u0433\u043e. \u0421\u0442\u0440\u043e\u043a\u0438 \u0443\u0436\u0435 \u0441\u043e\u0432\u043f\u0430\u0434\u0430\u044e\u0442, \u043b\u0438\u0431\u043e \u0447\u0430\u0441\u0442\u044c \u043f\u0440\u043e\u043f\u0443\u0449\u0435\u043d\u0430: \u0432 \u043e\u0434\u0438\u043d \u0434\u0435\u043d\u044c \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0442\u0440\u0435\u043d\u0438\u0440\u043e\u0432\u043e\u043a, \u0430 \u0441\u0442\u043e\u043b\u0431\u0446\u0430 id \u043d\u0435\u0442."},
oq(a,b,c,d,e){return"\u041e\u0431\u043d\u043e\u0432\u0438\u0442\u044c \u0442\u0440\u0435\u043d\u0438\u0440\u043e\u0432\u043e\u043a: "+a+". \u0414\u043e\u0431\u0430\u0432\u0438\u0442\u044c \u0442\u0440\u0435\u043d\u0438\u0440\u043e\u0432\u043e\u043a: "+b+". \u041d\u043e\u0432\u044b\u0445 \u043a\u043b\u0438\u0435\u043d\u0442\u043e\u0432: "+c+". \u041e\u0431\u043d\u043e\u0432\u0438\u0442\u044c \u043a\u043b\u0438\u0435\u043d\u0442\u043e\u0432: "+d+". \u041f\u0440\u043e\u043f\u0443\u0449\u0435\u043d\u043e \u0441\u0442\u0440\u043e\u043a: "+e+". \u0422\u0440\u0435\u043d\u0438\u0440\u043e\u0432\u043e\u043a, \u043a\u043e\u0442\u043e\u0440\u044b\u0445 \u043d\u0435\u0442 \u0432 \u0444\u0430\u0439\u043b\u0435, \u043d\u0430 \u0442\u0435\u043b\u0435\u0444\u043e\u043d\u0435 \u043d\u0435 \u0442\u0440\u043e\u0433\u0430\u0435\u043c. \u0422\u0440\u0435\u043d\u0438\u0440\u043e\u0432\u043a\u0430 \u0438\u0437 \u0444\u0430\u0439\u043b\u0430 \u0437\u0430\u043c\u0435\u043d\u044f\u0435\u0442 \u0441\u0432\u043e\u0438 \u043f\u043e\u0434\u0445\u043e\u0434\u044b."},
gom(){return"\u0418\u043c\u043f\u043e\u0440\u0442\u0438\u0440\u043e\u0432\u0430\u0442\u044c"},
gor(){return"\u0422\u0430\u0431\u043b\u0438\u0446\u0430 \u0438\u043c\u043f\u043e\u0440\u0442\u0438\u0440\u043e\u0432\u0430\u043d\u0430"},
gtE(){return"Google \u0422\u0430\u0431\u043b\u0438\u0446\u044b"},
gtD(){return"\u0412 \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u0435 \u043c\u043e\u0436\u043d\u043e \u043e\u0442\u043f\u0440\u0430\u0432\u0438\u0442\u044c \u0442\u0430\u0431\u043b\u0438\u0446\u0443 \u0432 Google \u0422\u0430\u0431\u043b\u0438\u0446\u044b \u0438\u043b\u0438 Excel. \u041f\u043e\u043f\u0440\u0430\u0432\u044c\u0442\u0435 \u043f\u043e\u0434\u0445\u043e\u0434\u044b \u0434\u043e\u043c\u0430, \u0441\u043a\u0430\u0447\u0430\u0439\u0442\u0435 CSV \u0438 \u0438\u043c\u043f\u043e\u0440\u0442\u0438\u0440\u0443\u0439\u0442\u0435 \u043e\u0431\u0440\u0430\u0442\u043d\u043e. \u0421\u0442\u043e\u043b\u0431\u0446\u044b id \u043d\u0435 \u0443\u0434\u0430\u043b\u044f\u0439\u0442\u0435, \u0430 \u0441\u0442\u0440\u043e\u043a\u0438 \u043e\u0434\u043d\u043e\u0433\u043e \u0443\u043f\u0440\u0430\u0436\u043d\u0435\u043d\u0438\u044f \u0434\u0435\u0440\u0436\u0438\u0442\u0435 \u0432\u043c\u0435\u0441\u0442\u0435 \u043f\u043e \u043f\u043e\u0440\u044f\u0434\u043a\u0443. \u0422\u0440\u0435\u043d\u0438\u0440\u043e\u0432\u043a\u0430 \u0438\u0437 \u0444\u0430\u0439\u043b\u0430 \u0437\u0430\u043c\u0435\u043d\u044f\u0435\u0442 \u0441\u0432\u043e\u0438 \u043f\u043e\u0434\u0445\u043e\u0434\u044b. \u0422\u0440\u0435\u043d\u0438\u0440\u043e\u0432\u043a\u0438, \u043a\u043e\u0442\u043e\u0440\u044b\u0445 \u0432 \u0444\u0430\u0439\u043b\u0435 \u043d\u0435\u0442, \u043e\u0441\u0442\u0430\u044e\u0442\u0441\u044f. \u0418\u043c\u044f, \u0446\u0435\u043b\u044c \u0438 \u0437\u0430\u043c\u0435\u0442\u043a\u0438 \u043a\u043b\u0438\u0435\u043d\u0442\u0430 \u0431\u0435\u0440\u0443\u0442\u0441\u044f \u0438\u0437 \u043f\u0435\u0440\u0432\u043e\u0439 \u0437\u0430\u043f\u043e\u043b\u043d\u0435\u043d\u043d\u043e\u0439 \u0441\u0442\u0440\u043e\u043a\u0438. \u0417\u0430\u043c\u0435\u0442\u043a\u0430 \u043a \u0443\u043f\u0440\u0430\u0436\u043d\u0435\u043d\u0438\u044e \u0438 \u0437\u0430\u043c\u0435\u0442\u043a\u0430 \u043a \u0442\u0440\u0435\u043d\u0438\u0440\u043e\u0432\u043a\u0435 \u0432\u043e\u0437\u0432\u0440\u0430\u0449\u0430\u044e\u0442\u0441\u044f \u0432\u043c\u0435\u0441\u0442\u0435 \u0441 \u0444\u0430\u0439\u043b\u043e\u043c. \u0424\u0430\u0439\u043b \u0431\u0435\u0437 \u044d\u0442\u0438\u0445 \u0441\u0442\u043e\u043b\u0431\u0446\u043e\u0432 \u043d\u0435 \u0441\u0442\u0438\u0440\u0430\u0435\u0442 \u0437\u0430\u043c\u0435\u0442\u043a\u0438, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u0443\u0436\u0435 \u0435\u0441\u0442\u044c \u043d\u0430 \u0442\u0435\u043b\u0435\u0444\u043e\u043d\u0435. \u041f\u043e\u043b\u043d\u0430\u044f \u043a\u043e\u043f\u0438\u044f \u043f\u043e-\u043f\u0440\u0435\u0436\u043d\u0435\u043c\u0443 \u0432 JSON."},
gv9(){return"\u0414\u043e\u0431\u0430\u0432\u0438\u0442\u044c \u0443\u0432\u0435\u0434\u043e\u043c\u043b\u0435\u043d\u0438\u0435 \u0437\u0430"},
