vg(a,b){var s="\u0417\u0430\u0432\u0442\u0440\u0430 \u0443 \u0432\u0430\u0441 "+a,r=s+" \u0442\u0440\u0435\u043d\u0438\u0440\u043e\u0432\u043e\u043a, \u043f\u0435\u0440\u0432\u0430\u044f \u043d\u0430\u0447\u043d\u0451\u0442\u0441\u044f \u0432 "+b+"."
return A.fG(a,s+" \u0442\u0440\u0435\u043d\u0438\u0440\u043e\u0432\u043a\u0438, \u043f\u0435\u0440\u0432\u0430\u044f \u043d\u0430\u0447\u043d\u0451\u0442\u0441\u044f \u0432 "+b+".",this.a,r,"\u0417\u0430\u0432\u0442\u0440\u0430 \u0443 \u0432\u0430\u0441 \u043e\u0434\u043d\u0430 \u0442\u0440\u0435\u043d\u0438\u0440\u043e\u0432\u043a\u0430, \u043e\u043d\u0430 \u043d\u0430\u0447\u043d\u0451\u0442\u0441\u044f \u0432 "+b+".",r,null,null)},
